"""Python engine: SciPy (and statsmodels for regression)."""

from __future__ import annotations

import json
import sys

from .. import __version__
from .base import EngineAdapter

PRELUDE = '''\
#!/usr/bin/env python3
# Generated by aistat __AISTAT_VERSION__ for __RUN_ID__ (__METHOD__).
# Re-run from this folder:  python analysis.py [data.csv] [raw_outputs/results.json]
import json
import math
import platform
import sys

import numpy as np
import pandas as pd
import scipy
from scipy import stats

PLAN = json.loads(__PLAN_JSON__)
DATA = sys.argv[1] if len(sys.argv) > 1 else __DEFAULT_DATA__
OUT = sys.argv[2] if len(sys.argv) > 2 else "raw_outputs/results.json"
V, O = PLAN["variables"], PLAN["options"]
ENGINE_VERSION = [f"Python {platform.python_version()}", f"SciPy {scipy.__version__}", f"pandas {pd.__version__}"]


def clean(x):
    if isinstance(x, dict):
        return {str(k): clean(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [clean(v) for v in x]
    if isinstance(x, (bool, np.bool_)):
        return bool(x)
    if isinstance(x, (int, np.integer)):
        return int(x)
    if isinstance(x, (float, np.floating)):
        return float(x) if math.isfinite(x) else None
    return x


def shapiro(values, check_id, label):
    values = np.asarray(values, dtype=float)
    base = {"id": check_id, "label": label, "test": "Shapiro-Wilk", "n": int(len(values))}
    if not 3 <= len(values) <= 5000 or np.ptp(values) == 0:
        return {**base, "statistic": None, "p": None, "violated": None, "note": "樣本數或變異不足，無法檢定"}
    w, p = stats.shapiro(values)
    return {**base, "statistic": float(w), "p": float(p), "violated": bool(p < O["alpha"])}


df = pd.read_csv(DATA, encoding="utf-8", dtype={c: str for c in PLAN.get("string_columns", [])})
statistics, assumptions, warnings = {}, [], []
'''

FOOTER = '''
result = {
    "engine": {"name": "python", "version": "; ".join(ENGINE_VERSION)},
    "method": PLAN["method"],
    "run_id": PLAN["run_id"],
    "n_input_rows": int(len(df)),
    "statistics": statistics,
    "assumptions": assumptions,
    "warnings": warnings,
}
with open(OUT, "w", encoding="utf-8") as f:
    json.dump(clean(result), f, ensure_ascii=False, indent=2, allow_nan=False)
'''

METHOD_CODE = {
    "independent-t-test": '''
y, g = V["outcome"], V["group"]
d = df[[y, g]].dropna()
L1, L2 = PLAN["levels"]["group"]
x1 = d.loc[d[g] == L1, y].to_numpy(dtype=float)
x2 = d.loc[d[g] == L2, y].to_numpy(dtype=float)
n1, n2 = len(x1), len(x2)


def ttest(equal_var):
    r = stats.ttest_ind(x1, x2, equal_var=equal_var)
    ci = r.confidence_interval(confidence_level=O["conf_level"])
    return {"t": r.statistic, "df": r.df, "p": r.pvalue, "ci_lower": ci.low, "ci_upper": ci.high}


pooled_sd = math.sqrt(((n1 - 1) * np.var(x1, ddof=1) + (n2 - 1) * np.var(x2, ddof=1)) / (n1 + n2 - 2))
statistics = {
    "n": n1 + n2,
    "n_excluded": len(df) - (n1 + n2),
    "groups": [{"level": L1, "n": n1, "mean": x1.mean(), "sd": np.std(x1, ddof=1)},
               {"level": L2, "n": n2, "mean": x2.mean(), "sd": np.std(x2, ddof=1)}],
    "mean_diff": x1.mean() - x2.mean(),
    "welch": ttest(False),
    "student": ttest(True),
    "pooled_sd": pooled_sd,
    "cohens_d": (x1.mean() - x2.mean()) / pooled_sd if pooled_sd > 0 else None,
    "conf_level": O["conf_level"],
}
lev = stats.levene(x1, x2, center="median")
assumptions = [
    {**shapiro(x1, "normality_by_group", f"{L1} 組常態性"), "group": L1},
    {**shapiro(x2, "normality_by_group", f"{L2} 組常態性"), "group": L2},
    {"id": "homogeneity_of_variance", "label": "變異數同質性", "test": "Brown-Forsythe Levene",
     "statistic": lev.statistic, "p": lev.pvalue, "df1": 1, "df2": n1 + n2 - 2,
     "violated": bool(lev.pvalue < O["alpha"]), "informational": True},
]
''',
    "paired-t-test": '''
d = df[[V["before"], V["after"]]].dropna()
before = d[V["before"]].to_numpy(dtype=float)
after = d[V["after"]].to_numpy(dtype=float)
diff = after - before
n = len(diff)
res = stats.ttest_rel(after, before)
ci = res.confidence_interval(confidence_level=O["conf_level"])
sd_diff = float(np.std(diff, ddof=1))
statistics = {
    "n": n,
    "n_excluded": len(df) - n,
    "mean_before": before.mean(), "sd_before": np.std(before, ddof=1),
    "mean_after": after.mean(), "sd_after": np.std(after, ddof=1),
    "mean_diff": diff.mean(), "sd_diff": sd_diff, "se_diff": sd_diff / math.sqrt(n),
    "t": res.statistic, "df": res.df, "p": res.pvalue,
    "ci_lower": ci.low, "ci_upper": ci.high, "conf_level": O["conf_level"],
    "cohens_dz": diff.mean() / sd_diff if sd_diff > 0 else None,
}
assumptions = [shapiro(diff, "normality_of_differences", "差值常態性")]
''',
}


class PythonEngine(EngineAdapter):
    name = "python"
    script_name = "analysis.py"
    install_hint = "請安裝 scipy、pandas、statsmodels。"

    def command(self) -> list[str] | None:
        # -I: isolated mode, so files in the run folder cannot shadow library modules.
        return [sys.executable, "-I"]

    def render_script(self, plan: dict, default_data: str) -> str:
        body = METHOD_CODE[plan["method"]]
        head = (
            PRELUDE.replace("__AISTAT_VERSION__", __version__)
            .replace("__RUN_ID__", plan["run_id"])
            .replace("__METHOD__", plan["method"])
            .replace("__PLAN_JSON__", repr(json.dumps(plan, ensure_ascii=False)))
            .replace("__DEFAULT_DATA__", repr(default_data))
        )
        return head + body + FOOTER
